-- Verified review of eleven previously pending staged records; complete worked reasons retained.
DO $review$
DECLARE v jsonb;b public.question_bank%rowtype; qid uuid; c jsonb;status_ text;
BEGIN
 FOR v IN SELECT value FROM jsonb_array_elements($payload$[{"id": "college_panda_10_practice_tests-test01-s3-q16", "status": "review_required", "explanation": "|1 − x| > 4 gives x < −3 or x > 5. Since x is positive, every real x > 5 is valid.", "note": "Rechecked algebra. Retain release hold: the grader must accept the full open range x > 5, not one sample response.", "before_stem": "If |1 − x| > 4 and x is positive, what is one possible value of x?", "source_id": "college_panda_10_practice_tests", "page": 8, "stem": "If |1 − x| > 4 and x is positive, what is one possible value of x?", "key": null, "duplicate_of": null}, {"id": "college_panda_10_practice_tests-test01-s4-q33", "status": "review_required", "explanation": "Over the real numbers the square root is undefined when (x − 1)(x − 2) < 0, exactly when 1 < x < 2. Endpoints are defined.", "note": "Rechecked sign intervals and endpoints. Retain release hold: numeric interval grading is required.", "before_stem": "For g(x) = √[(x − 1)(x − 2)], what is one possible value of x for which g is undefined over the real numbers?", "source_id": "college_panda_10_practice_tests", "page": 18, "stem": "For g(x) = √[(x − 1)(x − 2)], what is one possible value of x for which g is undefined over the real numbers?", "key": null, "duplicate_of": null}, {"id": "est1_dec_2025-q00019", "status": "review_required", "explanation": "Completing the square gives 4x² − 12x + 52 = 4(x − 3/2)² + 43. If the intended form were 4(x − n)² + m, mn would be 129/2. The printed form instead says 4(x − n)² = m; that does not define such an identity.", "note": "Original page 6 visually rechecked. The source equation is defective; do not silently replace its equality sign by a plus sign.", "before_stem": "20. If 4x 2 12x 52 is written as 4(x n)2 m, what is the value of (m n)?", "source_id": "est1_dec_2025", "page": 6, "stem": "20. If 4x 2 12x 52 is written as 4(x n)2 m, what is the value of (m n)?", "key": null, "duplicate_of": null}, {"id": "est1_dec_2025-q00022", "status": "published", "explanation": "The decrease is 1200 − 1090 = $110. Relative to the original price, the decrease is 100(110/1200) = 55/6% ≈ 9.1667%, which rounds to 9%.", "note": "Original page 7 visually checked. Added an explicit nearest-whole-percent instruction; choice B is now unambiguous.", "before_stem": "23. A car price changed by x%, find x. If the car originaly 1200$ and now 1090$?", "source_id": "est1_dec_2025", "page": 7, "stem": "A car price decreases from $1,200 to $1,090. What is the percentage decrease, rounded to the nearest whole percent?", "key": "B", "duplicate_of": null, "question_id": "9d2cab38-e5c2-5d64-99cd-302916543d71", "choices": [{"key": "A", "text": "10%"}, {"key": "B", "text": "9%"}, {"key": "C", "text": "6%"}, {"key": "D", "text": "12%"}], "type": "mcq"}, {"id": "est1_dec_2025-q00023", "status": "duplicate", "explanation": "Each word takes 60/10 = 6 seconds. In 80 seconds, 13 complete words take 78 seconds; 14 would take 84 seconds.", "note": "Original page 7 checked. Canonical reviewed version explicitly asks for complete words; linked instead of publishing another duplicate.", "before_stem": "24. Ahmed can spell 10 words in 60 seconds.How many words can he spell in 1 minute 20 seconds?", "source_id": "est1_dec_2025", "page": 7, "stem": "24. Ahmed can spell 10 words in 60 seconds.How many words can he spell in 1 minute 20 seconds?", "key": "C", "duplicate_of": "07691b4d-a501-d076-8818-3cd9557a401d"}, {"id": "est1_dec_2025-q00024", "status": "published", "explanation": "Write the equation as 2x² − 3mx + (v − 9) = 0. By Vieta the sum of its roots is −(−3m)/2 = 3m/2. Thus 3m/2 = 4, and m = 8/3. The constant v does not change the sum of roots.", "note": "Original page 7 visually checked. None of the printed options equals 8/3; released as a numeric response with the mathematically correct key.", "before_stem": "25. The sum of roots of 2x 2 3mx v 9 is 4, what is the value of m?", "source_id": "est1_dec_2025", "page": 7, "stem": "The sum of the two roots of 2x² − 3mx + v = 9 is 4. What is m? Enter an exact fraction.", "key": ["8/3"], "duplicate_of": null, "question_id": "a6225a2b-a8fb-5212-8acf-5a369d969fc8", "choices": [], "type": "grid_in"}, {"id": "est1_dec_2025-q00033", "status": "published", "explanation": "Expand and combine: 4x² + 20x − 12 + 6x² + 18x + 30 = 10x² + 38x + 18. The coefficient of x² is 10.", "note": "Original page 9 visually checked. Isolated Q35 from the merged Q35–37 OCR record and restored its four actual choices.", "before_stem": "35. Find the coff of x2 in the expression 4(x 2 5x 3) 6(x 2 3x 5)", "source_id": "est1_dec_2025", "page": 9, "stem": "What is the coefficient of x² in 4(x² + 5x − 3) + 6(x² + 3x + 5)?", "key": "C", "duplicate_of": null, "question_id": "614bd280-812d-5337-be7f-873789bddd63", "choices": [{"key": "A", "text": "4"}, {"key": "B", "text": "6"}, {"key": "C", "text": "10"}, {"key": "D", "text": "24"}], "type": "mcq"}, {"id": "est2_hs_level1_jan_2026-q00041", "status": "published", "explanation": "The square root requires x ≥ 3/2 and takes every value from 0 to infinity. Therefore 2 − √(2x − 3) takes every value at most 2. It attains 2 at x = 3/2, so the range is (−∞,2], including the upper endpoint.", "note": "Original page 19 visually checked. Corrected the missing closed endpoint in choice A and wrote valid interval notation for the distractors.", "before_stem": "Find the range of y = 2 − √(2x − 3).", "source_id": "est2_hs_level1_jan_2026", "page": 19, "stem": "What is the range of y = 2 − √(2x − 3) over the real numbers?", "key": "A", "duplicate_of": null, "question_id": "e4add89b-9a8b-5d3a-9846-be4df53ea118", "choices": [{"key": "A", "text": "(−∞, 2]"}, {"key": "B", "text": "(−∞, −2)"}, {"key": "C", "text": "(2, ∞)"}, {"key": "D", "text": "(−2, ∞)"}, {"key": "E", "text": "(−∞, 1.5)"}], "type": "mcq"}, {"id": "est2_hs_level1_jan_2026-q00054", "status": "review_required", "explanation": "Putting x = y = z = r gives 16r² − 4r − 110 = 0, or (4r − 11)(2r + 5) = 0. Thus r = 11/4 or −5/2 and 4r³ is 83.1875 or −62.5. Neither exact value is listed, and positivity is not specified.", "note": "Original page 27 visually rechecked. Retain hold: two admissible values and no exact printed answer.", "before_stem": "Given 4x² + 8xz + 4y² − 4y = 110, find 4r³ if x = y = z = r.", "source_id": "est2_hs_level1_jan_2026", "page": 27, "stem": "Given 4x² + 8xz + 4y² − 4y = 110, find 4r³ if x = y = z = r.", "key": null, "duplicate_of": null}, {"id": "ghoneem_full_revision_jun_2026-q00005", "status": "published", "explanation": "B gives −4 < 3x + 7 < 4, hence −11/3 < x < −1, an interval containing infinitely many reals. D is true for every real x because |−4x + 1| ≥ 0 > −5. A and C each have one solution. Both B and D are valid and accepted.", "note": "Original page 3 visually checked. Explicitly allow any valid option; accept both B and D in the existing multi-key grader.", "before_stem": "Q5. Which of the following has infinitely many solutions?", "source_id": "ghoneem_full_revision_jun_2026", "page": 3, "stem": "Which option has infinitely many real solutions? Choose any valid option.", "key": ["B", "D"], "duplicate_of": null, "question_id": "19ca085e-682e-5f7e-97d7-b1a5daea2318", "choices": [{"key": "A", "text": "4x − 1 = 9"}, {"key": "B", "text": "|3x + 7| < 4"}, {"key": "C", "text": "2x − 6 = 3(x + 7)"}, {"key": "D", "text": "|−4x + 1| > −5"}], "type": "mcq"}, {"id": "statistics_probability_hw_aug_2026-q00006", "status": "review_required", "explanation": "The old total is 160 + 170 + 180 = 510 cm, and the new total is 3 × 175 = 525 cm. If the departing height is d and the newcomer has height h, then 510 − d + h = 525, so h = d + 15. The possible heights are 175, 185, and 195 cm.", "note": "Original page 3 visually rechecked. Retain hold: the departing person is not identified; a single listed plausible value does not make the question determinate.", "before_stem": "Q6. Three people: 160, 170, 180 cm. One leaves, another joins. New mean = 175. New\n person's height?", "source_id": "statistics_probability_hw_aug_2026", "page": 3, "stem": "Q6. Three people: 160, 170, 180 cm. One leaves, another joins. New mean = 175. New\n person's height?", "key": null, "duplicate_of": null}]$payload$::jsonb) LOOP
  IF EXISTS(SELECT 1 FROM public.audit_log WHERE action='staged_final_review_20260928' AND target_id=v->>'id') THEN CONTINUE;END IF;
  SELECT * INTO b FROM public.question_bank WHERE question_id=v->>'id' FOR UPDATE;
  IF b.question_id IS NULL OR b.publication_status<>'review_required' OR b.stem_text IS DISTINCT FROM v->>'before_stem' THEN RAISE EXCEPTION 'Changed staged record %',v->>'id';END IF;
  INSERT INTO public.audit_log(action,target_type,target_id,meta) VALUES('staged_final_review_20260928','question_bank',b.question_id,jsonb_build_object('before',to_jsonb(b),'decision',v));
  status_=v->>'status';
  IF status_='published' THEN
   qid=(v->>'question_id')::uuid;
   IF EXISTS(SELECT 1 FROM public.questions WHERE id=qid OR assets->>'source_question_id'=b.question_id) THEN RAISE EXCEPTION 'Existing live staged question %',b.question_id; END IF;
   IF v->>'type'='mcq' THEN
    FOR c IN SELECT value FROM jsonb_array_elements(CASE WHEN jsonb_typeof(v->'key')='array' THEN v->'key' ELSE jsonb_build_array(v->'key') END) LOOP
     IF NOT EXISTS(SELECT 1 FROM jsonb_array_elements(v->'choices') x WHERE x->>'key'=c#>>'{}') OR NOT public.answer_matches('mcq',c,v->'key') THEN RAISE EXCEPTION 'Invalid MCQ key %',b.question_id; END IF;
    END LOOP;
   ELSIF NOT public.answer_matches('grid_in',v->'key'->0,v->'key') THEN RAISE EXCEPTION 'Invalid numeric key %',b.question_id; END IF;
   INSERT INTO public.questions(id,track_id,topic,difficulty,type,stem,choices,assets) VALUES(qid,'est',coalesce(b.primary_lesson,'Algebra Foundations, Equations & Inequalities'),'medium',v->>'type',v->>'stem',v->'choices',jsonb_build_object('source_id',b.source_id,'source_question_id',b.question_id,'source_page',b.source_pdf_page,'verified_release','2026-09-28-independent-solution-and-source-check','answer_review','2026-09-28-independent-solution-and-source-check','verification_note',v->>'note'));
   INSERT INTO public.question_keys(question_id,correct,explanation) VALUES(qid,v->'key',v->>'explanation');
  END IF;
  UPDATE public.question_bank SET publication_status=status_,needs_review=(status_='review_required'),
   stem_text=v->>'stem',choices=CASE WHEN status_='published' THEN coalesce((SELECT jsonb_object_agg(x->>'key',x->>'text') FROM jsonb_array_elements(v->'choices') x),'{}'::jsonb) ELSE b.choices END,
   answer_key=CASE WHEN v->'key'='null'::jsonb THEN b.answer_key ELSE v->'key'#>>'{}' END,
   answer_explanation=v->>'explanation',answer_key_status=CASE WHEN status_='published' THEN 'independently_verified' WHEN status_='duplicate' THEN 'verified_duplicate' ELSE 'rechecked_blocked' END,
   review_reasons=jsonb_build_array('Rechecked 2026-09-28. '||(v->>'note'))||CASE WHEN v->>'duplicate_of' IS NOT NULL THEN jsonb_build_array('Canonical live question: '||(v->>'duplicate_of')) ELSE '[]'::jsonb END
   WHERE question_id=b.question_id;
 END LOOP;
END;$review$;
-- These legacy OCR chunks have neither a key nor explanation and no linked live question.
-- Preserve every raw row, but remove the misleading published label. No live question is removed.
DO $quarantine$
DECLARE b public.question_bank%rowtype;n integer:=0;
BEGIN
 FOR b IN SELECT * FROM public.question_bank WHERE publication_status='published' AND needs_review AND answer_key IS NULL AND coalesce(answer_explanation,'')='' FOR UPDATE LOOP
  IF EXISTS(SELECT 1 FROM public.questions q WHERE q.assets->>'source_question_id'=b.question_id) THEN RAISE EXCEPTION 'Unexpected live link %',b.question_id; END IF;
  INSERT INTO public.audit_log(action,target_type,target_id,meta) VALUES('legacy_ocr_quarantine_20260928','question_bank',b.question_id,jsonb_build_object('before',to_jsonb(b),'reason','Unlinked raw OCR chunk with no answer or explanation; requires separation and source reconstruction'));
  UPDATE public.question_bank SET publication_status='review_required',answer_key_status='reconstruction_required',review_reasons=coalesce(review_reasons,'[]'::jsonb)||jsonb_build_array('Structural review 2026-09-28: unlinked raw OCR chunk without a key or explanation. Mixed question/solution content must be separated and independently verified before publication.') WHERE question_id=b.question_id;
  n=n+1;
 END LOOP;
 RAISE NOTICE 'Legacy raw chunks quarantined: %',n;
END;$quarantine$;
SELECT publication_status,needs_review,count(*) FROM public.question_bank GROUP BY 1,2 ORDER BY 1,2;
